import bcrypt

# Function to hash a password
def hash_password(password):
    return bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt())

# Function to validate a password
def validate_password(stored_password, provided_password):
    return bcrypt.checkpw(provided_password.encode('utf-8'), stored_password)

# Example usage
hashed = hash_password("mySecretPassword")
assert validate_password(hashed, "mySecretPassword") == True
assert validate_password(hashed, "wrongPassword") == False

print("Password validation works correctly.")
